#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Define a struct to represent a Roman numeral
typedef struct {
    char *symbol;
    int value;
} RomanNumeral;

// Define an array of Roman numerals
RomanNumeral romanNumerals[] = {
    {"M", 1000},
    {"CM", 900},
    {"D", 500},
    {"CD", 400},
    {"C", 100},
    {"XC", 90},
    {"L", 50},
    {"XL", 40},
    {"X", 10},
    {"IX", 9},
    {"V", 5},
    {"IV", 4},
    {"I", 1}
};

// Function to convert a Roman numeral to an integer
int romanToInt(char *s) {
    int result = 0;
    int i = 0;
    while (i < strlen(s)) {
        // Check if the current numeral is a subtractive pair
        if (i + 1 < strlen(s)) {
            int j;
            for (j = 0; j < sizeof(romanNumerals) / sizeof(romanNumerals[0]); j++) {
                if (strncmp(s + i, romanNumerals[j].symbol, strlen(romanNumerals[j].symbol)) == 0) {
                    result += romanNumerals[j].value;
                    i += strlen(romanNumerals[j].symbol);
                    break;
                }
            }
            if (j == sizeof(romanNumerals) / sizeof(romanNumerals[0])) {
                // If not a subtractive pair, add the value of the current numeral
                for (j = 0; j < sizeof(romanNumerals) / sizeof(romanNumerals[0]); j++) {
                    if (romanNumerals[j].symbol[0] == s[i]) {
                        result += romanNumerals[j].value;
                        i++;
                        break;
                    }
                }
            }
        } else {
            // If not a subtractive pair, add the value of the current numeral
            for (int j = 0; j < sizeof(romanNumerals) / sizeof(romanNumerals[0]); j++) {
                if (romanNumerals[j].symbol[0] == s[i]) {
                    result += romanNumerals[j].value;
                    i++;
                    break;
                }
            }
        }
    }
    return result;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <Roman numeral>\n", argv[0]);
        return 1;
    }
    char *romanNumeral = argv[1];
    int result = romanToInt(romanNumeral);
    printf("%d\n", result);
    return 0;
}
